node.interaction_0_script_to_test_if_interact:
function IsInteractionAvailable(so_self, so_activator)
{

	local num_investigated = Game_GetWorldStateAsInteger("MANA_CHAMBERS", "num_investigated", 0);
	local powered = StageObject_GetKeyValue(so_self, "powered", false);

	// debug
	//num_investigated = !;

	if (num_investigated >= 1 && powered)
	{

		local duration = StageObject_GetKeyValue(so_self, "duration", 0);
		local cooldown = StageObject_GetKeyValue(so_self, "cooldown", 0);
		local time_activated = StageObject_GetKeyValue(so_self, "time_activated", 0);
		local world_time = Game_GetWorldTimeSecondsAsRealTimeSeconds();

		if (time_activated == 0 || world_time > time_activated + duration + cooldown)
		{
			return true;
		}
	}

	return false;
}

node.interaction_0_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	if(!Game_IsStagePointOfInterestCompleted(so_self))
		Game_SetStagePointOfInterestCompleted(so_self);

	local duration = StageObject_GetKeyValue(so_self, "duration", 0);
	local cooldown = StageObject_GetKeyValue(so_self, "cooldown", 0);
	local time_activated = StageObject_GetKeyValue(so_self, "time_activated", 0);
	local world_time = Game_GetWorldTimeSecondsAsRealTimeSeconds();

	local quest_id = "quests/mana-chamber-intro.nut";
	Game_SendQuestPhaseCommandWord(quest_id, "PHASE_USE", "activate");

	if (time_activated == 0 || world_time > time_activated + duration + cooldown)
	{
		StageObject_SetKeyValueInteger(so_self, "time_activated", world_time);
		Actor_PlayAnimation(so_self, "activate");
		Game_ActivateManaChamber(so_self);

		//Raise the dead
		if(StageObject_GetKeyValue(so_self,"raise_dead") == false)
			return;


		local radius = StageObject_GetKeyValue(so_self,"radius");
		local pos = StageObject_GetPosition(so_self);
		local arr_so = Stage_QueryStageObjectsInRadius(pos[0],pos[1],pos[2],radius)


		if (arr_so != null)
		{
			foreach (so in arr_so)
			{
				if(StageObject_HasTag(so, "BOSS"))
					  continue;

				if(StageObject_HasTag(so, "NO_RESURRECTION"))
					  continue;



				if(StageObject_HasTag(so, "MONSTER")){

					local hitpoints = Actor_GetAttributeHitPoints(so)

					//is alive
					if(hitpoints > 0){
						continue;
					}
					else{

						local pos_enemy = StageObject_GetPosition(so);
						local puid = StageObject_GetPersistentUniqueId(so)
						StageObject_SetVisible(so, false)

						//respawn
						local actor_type = Actor_GetActorType(so)
						local new_enemy = Stage_CreateActor(actor_type, pos_enemy[0], pos_enemy[1], pos_enemy[2], true);

						StageObject_SetGlobal(new_enemy, false)


						Stage_SpawnEffect("effects/dead-rising.xml", pos_enemy[0], pos_enemy[1], pos_enemy[2] - 90, 0);

						//quest check
						if(Game_IsQuestCurrent(quest_id) && Game_GetQuestPhaseId(quest_id) == "PHASE_FIGHT")
							Game_SendQuestPhaseGoalCommandWord(quest_id, "PHASE_FIGHT", "GOAL_RISE", "activate")


						Actor_QueueActionPlayAnimationWithParameters(new_enemy, "landing_damage", 0.6, 0.4, true);
						Actor_QueueActionPlayAnimationWithParameters(new_enemy, "spot_enemy", 0.6, 0.0, true);
						//Actor_QueueActionTurnTowardsPosition(new_enemy, pos[0],pos[1]);



						//remove corpse
						Stage_DeleteStageObject(so);

					}



				}


			}
		}




	}

}

node.interaction_1_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{

	local duration = StageObject_GetKeyValue(so_self, "duration", 0);
	local time_activated = StageObject_GetKeyValue(so_self, "time_activated", 0);
	local world_time = Game_GetWorldTimeSecondsAsRealTimeSeconds();

	if (time_activated > 0 && world_time < time_activated + duration)
	{
		Game_ActivateManaChamber(so_self);
		Actor_PlayAnimationWithDelayPlaybackSpeedAndPosition(so_self, "activate", 0, 1, 1);
	}

	local cost = StageObject_GetKeyValue(so_self, "cost");

	local text = "";
	local substrings = split(cost, "x, ");
	foreach (str in substrings)
	{
		if (str.len() <= 2)
		{
			text += str + "x";
		}
		else
		{
			text += "[MATERIAL_ICON=" + str + "]  ";
		}
	}
	rstrip(text);

	Actor_SetInteractionText(so_self, "power", Game_GetConvertedString(text));
}

node.interaction_2_script_to_test_if_interact:
function IsInteractionAvailable(so_self, so_activator)
{

	//debug
	//return false;

	local quest_id = "quests/mana-chamber-intro.nut";

	if (Game_IsQuestGoalCompleted(quest_id, "INVESTIGATE", "INVESTIGATE"))
		return false;

	return !Game_IsShowingActorNotification(so_activator) &&
		!StageObject_GetKeyValue(so_self, "investigated", false);
}

node.interaction_2_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local quest_id = "quests/mana-chamber-intro.nut";
	local num_investigated = Game_GetWorldStateAsInteger("MANA_CHAMBERS", "num_investigated", 0);

	if (!StageObject_GetKeyValue(so_self, "investigated", false))
	{
		StageObject_SetKeyValueBoolean(so_self, "investigated", true);
		Game_SendQuestPhaseCommandWord(quest_id, "INVESTIGATE", "activate");

		num_investigated++;
		Game_SetWorldState("MANA_CHAMBERS", "num_investigated", num_investigated.tostring());

	}

	if (num_investigated == 1)
	{
		Game_AddActorNotification(so_activator, LOC_TEXT("It has some instructions written on it."));
		Game_AddActorNotification(so_activator, LOC_TEXT("The device can help in fighting the monsters and gaining materials when it's active."));
	}
}

