node.interaction_5_script_to_run_on_interacti:
function GetDrop(so_actor, kv_string_drops){

  local kv_drops =  StageObject_GetKeyValue(so_actor, kv_string_drops);

  if(kv_drops == null)
	  return;

  local drops = string_tokenize(kv_drops);

  if(drops.len() == 0)
	  return;

  local roll = (((1.0 * rand()) / RAND_MAX) * drops.len()).tointeger();
  //local roll = m_randf(0,drops.len()).tointeger();

  return drops[roll];

}

function OnInteraction(so_self, so_activator)
{


	if(Game_IsManaChamberActive()){


		local so_actors = Stage_QueryStageObjectsWithTag(STAGE_OBJECT_TYPE_ACTOR, "INSIDE_MANA_CHAMBER");


		foreach (idx, so_actor in so_actors) {

			local kv_drops = StageObject_GetKeyValue(so_actor, "mana_chamber_drops_material_id");
			local kv_random_drops = StageObject_GetKeyValue(so_actor, "mana_chamber_drops_random_material_id");


			if(kv_drops == null){
			  local drop = GetDrop(so_self, "enemy_drops");
			  StageObject_SetKeyValueString(so_actor,"mana_chamber_drops_material_id", drop);
			}


			if(kv_random_drops == null){
			  local drop = GetDrop(so_self, "enemy_drops_random");
			  StageObject_SetKeyValueString(so_actor,"mana_chamber_drops_random_material_id", drop);

			}

		}


	}

}

node.interaction_6_script_to_test_if_interact:
function IsInteractionAvailable(so_self, so_activator)
{
	local duration = StageObject_GetKeyValue(so_self, "duration", 0);
	local cooldown = StageObject_GetKeyValue(so_self, "cooldown", 0);
	local time_activated = StageObject_GetKeyValue(so_self, "time_activated", 0);
	local world_time = Game_GetWorldTimeSecondsAsRealTimeSeconds();

	if (time_activated == 0 || world_time > time_activated + duration + cooldown || world_time < time_activated + duration + 1)
	{
		return false;
	}

	return true;
}

node.interaction_6_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	if (Game_IsShowingActorNotification(so_self))
		return;

	local duration = StageObject_GetKeyValue(so_self, "duration", 0);
	local cooldown = StageObject_GetKeyValue(so_self, "cooldown", 0);
	local time_activated = StageObject_GetKeyValue(so_self, "time_activated", 0);
	local world_time = Game_GetWorldTimeSecondsAsRealTimeSeconds();

	local time_left = time_activated + duration + cooldown - world_time;

	if (time_left > 0)
	{

		local minutes = floor(time_left / 60);
		local seconds = time_left - minutes * 60;
		local time_string = format("%.2d:%.2d", minutes, seconds);
		Game_AddActorNotification(so_self, "[EMOJI=hourglass not done] " + time_string);

	}





}
